     6→import { Music, ArrowRight, Disc } from "lucide-react";
     7→import { NeoNavbar } from "../NeoNavbar";
     8→import { NeoFooter } from "../NeoFooter";
     9→import { NeoHeroSection } from "../ui/NeoHeroSection";
    10→import { NeoCard } from "../ui/NeoCard";
    11→import { BrutalistButton } from "../ui/BrutalistButton";
    12→import { NeoTag } from "../ui/NeoTag";
    13→import { Link } from "@/i18n/routing";
    14→
    15→interface Album {
    16→  id: string;
    17→  title: string;
    18→  img: string | null;
    19→  style: string | null;
    20→  date: string;
    21→  listenLink: string | null;
    22→  collabName?: string | null;
    23→}
    24→
    25→interface NeoAlbumsPageProps {
    26→  albums: Album[];
    27→}
    28→
    29→const normalizeGenre = (style: string | null) => {
    30→  if (!style) return null;
    31→
    32→  const normalized = style
    33→    .toLowerCase()
    34→    .normalize("NFD")
    35→    .replace(/[\u0300-\u036f]/g, "");
    36→
    37→  if (normalized.includes("metal") || normalized.includes("hardcore")) return "Metal";
    38→  if (
    39→    normalized.includes("hip-hop") ||
    40→    normalized.includes("hip hop") ||
    41→    normalized.includes("rnb") ||
    42→    normalized.includes("trap")
    43→  )
    44→    return "Hip-Hop";
    45→  if (normalized.includes("ambient")) return "Ambient";
    46→  if (normalized.includes("synthwave")) return "Synthwave";
    47→  if (normalized.includes("cyberpunk")) return "Cyberpunk";
    48→  if (normalized.includes("bass")) return "Bass Music";
    49→  if (normalized.includes("pop punk") || normalized.includes("punk")) return "Pop Punk";
    50→  if (normalized.includes("all music genres")) return "Various";
    51→
    52→  return style;
    53→};
    54→
    55→const sortGenres = (genres: string[]) => {
    56→  const order = [
    57→    "Metal",
    58→    "Hip-Hop",
    59→    "Ambient",
    60→    "Bass Music",
    61→    "Synthwave",
    62→    "Cyberpunk",
    63→    "Pop Punk",
    64→    "Various",
    65→  ];
    66→
    67→  const orderIndex = (genre: string) => {
    68→    const index = order.indexOf(genre);
    69→    return index === -1 ? Number.POSITIVE_INFINITY : index;
    70→  };
    71→
    72→  return [...genres].sort((a, b) => {
    73→    const byOrder = orderIndex(a) - orderIndex(b);
    74→    if (byOrder !== 0) return byOrder;
    75→    return a.localeCompare(b);
    76→  });
    77→};
    78→
    79→const staggerContainer = {
    80→  hidden: { opacity: 0 },
    81→  visible: {
    82→    opacity: 1,
    83→    transition: { staggerChildren: 0.08, delayChildren: 0.1 },
    84→  },
    85→};
    86→
    87→const fadeInUp = {
    88→  hidden: { opacity: 0, y: 30, scale: 0.95 },
    89→  visible: { opacity: 1, y: 0, scale: 1, transition: { duration: 0.4 } },
    90→  exit: { opacity: 0, y: -20, scale: 0.95, transition: { duration: 0.3 } },
    91→};
    92→
    93→export const NeoAlbumsPage: React.FC<NeoAlbumsPageProps> = ({ albums }) => {
    94→  const t = useTranslations("albums");
    95→  const [selectedGenre, setSelectedGenre] = useState<string | null>(null);
    96→
    97→  const genreCounts = useMemo(() => {
    98→    const counts = new Map<string, number>();
    99→    for (const album of albums) {
   100→      const genre = normalizeGenre(album.style);
   101→      if (!genre) continue;
   102→      counts.set(genre, (counts.get(genre) ?? 0) + 1);
   103→    }
   104→    return counts;
   105→  }, [albums]);
   106→
   107→  // Extract unique genres
   108→  const genres = useMemo(() => {
   109→    return sortGenres(Array.from(genreCounts.keys()));
   110→  }, [genreCounts]);
   111→
   112→  // Filter albums by genre
   113→  const filteredAlbums = useMemo(() => {
   114→    return albums.filter((album) => {
   115→      const albumGenre = normalizeGenre(album.style);
   116→
   117→      const matchesGenre = !selectedGenre || albumGenre === selectedGenre;
   118→      if (!matchesGenre) return false;
   119→      return true;
   120→    });
   121→  }, [albums, selectedGenre]);
   122→
   123→  // Stats
   124→  const stats = useMemo(
   125→    () => ({
   126→      total: albums.length,
   127→      genres: genres.length,
   128→      collaborations: albums.filter((a) => a.collabName).length,
   129→      years: `${Math.min(...albums.map((a) => new Date(a.date).getFullYear()))}-${Math.max(...albums.map((a) => new Date(a.date).getFullYear()))}`,
   130→    }),
   131→    [albums, genres]
   132→  );
   133→
   134→  return (
   135→    <div className="min-h-screen bg-neo-bg text-neo-text font-sans selection:bg-neo-text selection:text-neo-accent overflow-x-hidden">
   136→      <NeoNavbar />
   137→
   138→      <main className="relative z-10 pt-16 md:pt-20">
   139→        {/* Hero */}
   140→        <NeoHeroSection
   141→          badgeNumber="04"
   142→          badge={t("hero.badge")}
   143→          title={t("hero.title")}
   144→          description={t("hero.description")}
   145→          fullViewport
   146→        >
   147→          <div className="flex flex-wrap gap-4">
   148→            <BrutalistButton
   149→              variant="primary"
   150→              size="lg"
   151→              icon={<Music className="w-5 h-5" />}
   152→              onClick={() =>
   153→                document.getElementById("albums-grid")?.scrollIntoView({ behavior: "smooth" })
   154→              }
   155→            >
   156→              {t("hero.cta")}
   157→            </BrutalistButton>
   158→            <Link href="/contact">
   159→              <BrutalistButton variant="secondary" size="lg">
   160→                {t("hero.ctaSecondary")}
   161→              </BrutalistButton>
   162→            </Link>
   163→          </div>
   164→        </NeoHeroSection>
   165→
   166→        {/* Stats Bar */}
   167→        <section className="border-y-4 border-neo-border bg-neo-text text-neo-text-inverse py-12">
   168→          <div className="container mx-auto px-4 md:px-6">
   169→            <div className="grid grid-cols-2 md:grid-cols-4 gap-8 text-center">
   170→              {[
   171→                { val: stats.total.toString(), label: t("stats.total") },
   172→                { val: stats.genres.toString(), label: t("stats.genres") },
   173→                { val: stats.collaborations.toString(), label: t("stats.collaborations") },
   174→                { val: stats.years, label: t("stats.period") },
   175→              ].map((stat, i) => (
   176→                <div key={i} className="flex flex-col items-center">
   177→                  <span className="text-4xl md:text-5xl font-black text-neo-accent tracking-tighter">
   178→                    {stat.val}
   179→                  </span>
   180→                  <span className="font-mono text-xs uppercase tracking-widest mt-2 opacity-60">
   181→                    {stat.label}
   182→                  </span>
   183→                </div>
   184→              ))}
   185→            </div>
   186→          </div>
   187→        </section>
   188→
   189→        {/* Filters */}
   190→        <section className="py-8 border-b-2 border-neo-border sticky top-[72px] bg-neo-bg z-30">
   191→          <div className="container mx-auto px-4 md:px-6">
   192→            <div className="flex flex-wrap gap-2">
   193→              <button
   194→                onClick={() => setSelectedGenre(null)}
   195→                className={`px-4 py-2 font-mono text-xs font-bold uppercase border-2 border-neo-border transition-all ${
   196→                  !selectedGenre
   197→                    ? "bg-neo-accent text-neo-text-inverse border-neo-accent"
   198→                    : "bg-neo-surface hover:bg-neo-accent hover:text-neo-text-inverse hover:border-neo-accent"
   199→                }`}
   200→              >
   201→                {t("filterAll")} ({albums.length})
   202→              </button>
   203→              {genres.map((genre) => (
   204→                <button
   205→                  key={genre}
   206→                  onClick={() => setSelectedGenre(genre)}
   207→                  className={`px-4 py-2 font-mono text-xs font-bold uppercase border-2 border-neo-border transition-all ${
   208→                    selectedGenre === genre
   209→                      ? "bg-neo-accent text-neo-text-inverse border-neo-accent"
   210→                      : "bg-neo-surface hover:bg-neo-accent hover:text-neo-text-inverse hover:border-neo-accent"
   211→                  }`}
   212→                >
   213→                  {genre} ({genreCounts.get(genre) ?? 0})
   214→                </button>
   215→              ))}
   216→            </div>
   217→          </div>
