   158→  --color-primary-200: #F2FFAB;
   159→  --color-primary-300: #E8FF75;
   160→  --color-primary-400: #D5FF0A;
   161→  --color-primary-500: #C2E600;
   162→  --color-primary-600: #9AB800;
   163→  --color-primary-700: #748A00;
   164→  --color-primary-800: #566900;
   165→  --color-primary-900: #2B3400;
   166→
   167→  /* Accent Colors */
   168→  --color-green: #5CE462;
   169→  --color-green-rgb: 92, 228, 98;
   170→  --color-emerald: #00C18B;
   171→  --color-emerald-rgb: 0, 193, 139;
   172→  --color-teal: #009998;
   173→  --color-teal-rgb: 0, 153, 152;
   174→  --color-ocean: #006F84;
   175→  --color-ocean-rgb: 0, 111, 132;
   176→  --color-slate: #2F4858;
   177→  --color-slate-rgb: 47, 72, 88;
   178→
   179→  /* Neutrals - Dark scale */
   180→  --color-neutral-950: #09090b;
   181→  --color-neutral-925: #121214;
   182→  --color-neutral-900: #18181b;
   183→  --color-neutral-850: #1f1f23;
   184→  --color-neutral-800: #27272a;
   185→  --color-neutral-700: #3f3f46;
   186→  --color-neutral-600: #52525b;
   187→  --color-neutral-500: #71717a;
   188→  --color-neutral-400: #a1a1aa;
   189→  --color-neutral-300: #d4d4d8;
   190→  --color-neutral-200: #e4e4e7;
   191→  --color-neutral-100: #f4f4f5;
   192→  --color-neutral-50: #fafafa;
   193→
   194→  /* RGB values for dynamic opacity */
   195→  --color-neutral-950-rgb: 9, 9, 11;
   196→  --color-neutral-900-rgb: 24, 24, 27;
   197→  --color-neutral-850-rgb: 31, 31, 35;
   198→  --color-neutral-800-rgb: 39, 39, 42;
   199→  --color-neutral-100-rgb: 244, 244, 245;
   200→  --color-neutral-50-rgb: 250, 250, 250;
   201→  --color-white-rgb: 255, 255, 255;
   202→  --color-black-rgb: 0, 0, 0;
   203→
   204→  /* Indigo for light mode accent */
   205→  --color-indigo: #4f46e5;
   206→  --color-indigo-rgb: 79, 70, 229;
   207→  --color-indigo-hover: #4338ca;
   208→  --color-indigo-light: #6366f1;
   209→
   210→  /* Semantic Colors */
   211→  --color-success: #5CE462;
   212→  --color-warning: #FBBF24;
   213→  --color-error: #EF4444;
   214→  --color-info: #009998;
   215→
   216→  /* ===== SPACING SCALE ===== */
   217→  --space-0: 0;
   218→  --space-px: 1px;
   219→  --space-0-5: 0.125rem;   /* 2px */
   220→  --space-1: 0.25rem;      /* 4px */
   221→  --space-1-5: 0.375rem;   /* 6px */
   222→  --space-2: 0.5rem;       /* 8px */
   223→  --space-2-5: 0.625rem;   /* 10px */
   224→  --space-3: 0.75rem;      /* 12px */
   225→  --space-3-5: 0.875rem;   /* 14px */
