   227→  --space-5: 1.25rem;      /* 20px */
   228→  --space-6: 1.5rem;       /* 24px */
   229→  --space-7: 1.75rem;      /* 28px */
   230→  --space-8: 2rem;         /* 32px */
   231→  --space-9: 2.25rem;      /* 36px */
   232→  --space-10: 2.5rem;      /* 40px */
   233→  --space-12: 3rem;        /* 48px */
   234→  --space-14: 3.5rem;      /* 56px */
   235→  --space-16: 4rem;        /* 64px */
   236→  --space-20: 5rem;        /* 80px */
   237→  --space-24: 6rem;        /* 96px */
   238→  --space-32: 8rem;        /* 128px */
   239→
   240→  /* ===== BORDER RADIUS ===== */
   241→  --radius-none: 0;
   242→  --radius-sm: 0.25rem;    /* 4px */
   243→  --radius-md: 0.5rem;     /* 8px */
   244→  --radius-lg: 0.75rem;    /* 12px */
   245→  --radius-xl: 1rem;       /* 16px */
   246→  --radius-2xl: 1.5rem;    /* 24px */
   247→  --radius-3xl: 2rem;      /* 32px */
   248→  --radius-full: 9999px;
   249→
   250→  /* ===== SHADOWS ===== */
   251→  --shadow-xs: 0 1px 2px 0 rgba(0, 0, 0, 0.4);
   252→  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.5), 0 1px 2px -1px rgba(0, 0, 0, 0.5);
   253→  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.5), 0 2px 4px -2px rgba(0, 0, 0, 0.5);
   254→  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.5), 0 4px 6px -4px rgba(0, 0, 0, 0.5);
   255→  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
   256→  --shadow-2xl: 0 25px 50px -12px rgba(0, 0, 0, 0.7);
   257→  --shadow-inner: inset 0 2px 4px 0 rgba(0, 0, 0, 0.3);
   258→
   259→  /* Glow Shadows - Primary (Neon Yellow) */
   260→  --glow-primary-sm: 0 0 10px -2px rgba(213, 255, 10, 0.4);
   261→  --glow-primary-md: 0 0 20px -4px rgba(213, 255, 10, 0.5);
   262→  --glow-primary-lg: 0 0 30px -6px rgba(213, 255, 10, 0.6);
   263→  --glow-primary-xl: 0 0 50px -10px rgba(213, 255, 10, 0.5);
   264→  --glow-primary-intense: 0 0 40px rgba(213, 255, 10, 0.8);
   265→
   266→  /* Glow Shadows - Green */
   267→  --glow-green-sm: 0 0 10px -2px rgba(92, 228, 98, 0.4);
   268→  --glow-green-md: 0 0 20px -4px rgba(92, 228, 98, 0.5);
   269→  --glow-green-lg: 0 0 30px -6px rgba(92, 228, 98, 0.6);
   270→
   271→  /* Glow Shadows - Emerald */
   272→  --glow-emerald-sm: 0 0 10px -2px rgba(0, 193, 139, 0.4);
   273→  --glow-emerald-md: 0 0 20px -4px rgba(0, 193, 139, 0.5);
   274→  --glow-emerald-lg: 0 0 30px -6px rgba(0, 193, 139, 0.6);
   275→
   276→  /* Glow Shadows - Teal */
   277→  --glow-teal-sm: 0 0 10px -2px rgba(0, 153, 152, 0.4);
   278→  --glow-teal-md: 0 0 20px -4px rgba(0, 153, 152, 0.5);
   279→  --glow-teal-lg: 0 0 30px -6px rgba(0, 153, 152, 0.6);
   280→
   281→  /* Glow Shadows - Ocean */
   282→  --glow-ocean-sm: 0 0 10px -2px rgba(0, 111, 132, 0.4);
   283→  --glow-ocean-md: 0 0 20px -4px rgba(0, 111, 132, 0.5);
   284→  --glow-ocean-lg: 0 0 30px -6px rgba(0, 111, 132, 0.6);
   285→
   286→  /* ===== TYPOGRAPHY ===== */
   287→  --font-sans: var(--font-inter), system-ui, -apple-system, sans-serif;
   288→  --font-display: var(--font-montserrat), system-ui, -apple-system, sans-serif;
   289→  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
   290→
   291→  /* Font Sizes */
   292→  --text-xs: 0.75rem;      /* 12px */
   293→  --text-sm: 0.875rem;     /* 14px */
   294→  --text-base: 1rem;       /* 16px */
   295→  --text-lg: 1.125rem;     /* 18px */
   296→  --text-xl: 1.25rem;      /* 20px */
   297→  --text-2xl: 1.5rem;      /* 24px */
   298→  --text-3xl: 1.875rem;    /* 30px */
   299→  --text-4xl: 2.25rem;     /* 36px */
   300→  --text-5xl: 3rem;        /* 48px */
   301→  --text-6xl: 3.75rem;     /* 60px */
   302→  --text-7xl: 4.5rem;      /* 72px */
   303→  --text-8xl: 6rem;        /* 96px */
   304→
   305→  /* Line Heights */
   306→  --leading-none: 1;
   307→  --leading-tight: 1.25;
   308→  --leading-snug: 1.375;
   309→  --leading-normal: 1.5;
   310→  --leading-relaxed: 1.625;
   311→  --leading-loose: 2;
   312→
   313→  /* Letter Spacing */
   314→  --tracking-tighter: -0.05em;
   315→  --tracking-tight: -0.025em;
   316→  --tracking-normal: 0;
   317→  --tracking-wide: 0.025em;
   318→  --tracking-wider: 0.05em;
   319→  --tracking-widest: 0.1em;
   320→
   321→  /* ===== TRANSITIONS ===== */
   322→  --duration-instant: 50ms;
   323→  --duration-fast: 150ms;
   324→  --duration-normal: 300ms;
   325→  --duration-slow: 500ms;
   326→  --duration-slower: 700ms;
   327→  --duration-slowest: 1000ms;
   328→
   329→  --ease-linear: linear;
   330→  --ease-in: cubic-bezier(0.4, 0, 1, 1);
   331→  --ease-out: cubic-bezier(0, 0, 0.2, 1);
   332→  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
   333→  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
   334→  --ease-bounce: cubic-bezier(0.68, -0.6, 0.32, 1.6);
   335→
   336→  /* ===== Z-INDEX SCALE ===== */
   337→  --z-behind: -1;
   338→  --z-base: 0;
   339→  --z-dropdown: 10;
   340→  --z-sticky: 20;
   341→  --z-fixed: 30;
   342→  --z-modal-backdrop: 40;
   343→  --z-modal: 50;
   344→  --z-popover: 60;
   345→  --z-tooltip: 70;
   346→  --z-toast: 80;
   347→
   348→  /* ===== GRADIENTS ===== */
   349→  --gradient-brand: linear-gradient(135deg, #D5FF0A 0%, #5CE462 25%, #00C18B 50%, #009998 75%, #006F84 100%);
   350→  --gradient-brand-short: linear-gradient(135deg, #D5FF0A 0%, #00C18B 100%);
   351→  --gradient-primary: linear-gradient(135deg, #D5FF0A 0%, #5CE462 100%);
   352→  --gradient-primary-teal: linear-gradient(135deg, #D5FF0A 0%, #009998 100%);
   353→  --gradient-teal: linear-gradient(135deg, #00C18B 0%, #006F84 100%);
   354→  --gradient-ocean: linear-gradient(135deg, #009998 0%, #2F4858 100%);
   355→  --gradient-surface: linear-gradient(180deg, #18181b 0%, #09090b 100%);
   356→
   357→  /* Glow Gradients (radial) */
   358→  --gradient-glow-primary: radial-gradient(ellipse 80% 50% at 50% -20%, rgba(213, 255, 10, 0.15), transparent);
   359→  --gradient-glow-teal: radial-gradient(ellipse 80% 50% at 50% -20%, rgba(0, 193, 139, 0.12), transparent);
   360→  --gradient-glow-center: radial-gradient(ellipse 50% 50% at 50% 50%, rgba(213, 255, 10, 0.08), transparent);
   361→}
   362→
   363→/* ===== LEGACY THEME VARIABLES ===== */
   364→/* Ces variables sont pour compatibilité avec l'ancien thème */
   365→.dark {
   366→  --background: var(--color-neutral-950);
   367→  --background-rgb: 9, 9, 11;
   368→  --foreground: var(--color-neutral-50);
   369→  --foreground-rgb: 250, 250, 250;
   370→
   371→  --surface: var(--color-neutral-900);
